import json

path = "issue10.jsonl"
with open(path) as f:
    lines = f.readlines()

print(f"total lines: {len(lines)}")
for i, line in enumerate(lines):
    try:
        obj = json.loads(line)
    except Exception as e:
        print(i, "PARSE ERROR", e)
        continue
    t = obj.get("type")
    ts = obj.get("timestamp", "")
    role = obj.get("message", {}).get("role") if isinstance(obj.get("message"), dict) else None
    content = obj.get("message", {}).get("content") if isinstance(obj.get("message"), dict) else None
    summary = ""
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                ctype = c.get("type")
                if ctype == "text":
                    txt = c.get("text", "")[:120].replace("\n"," ")
                    parts.append(f"[text]{txt}")
                elif ctype == "tool_use":
                    parts.append(f"[tool_use:{c.get('name')}]")
                elif ctype == "tool_result":
                    tc = c.get("content")
                    if isinstance(tc, list):
                        tlen = sum(len(x.get("text","")) for x in tc if isinstance(x,dict))
                    else:
                        tlen = len(str(tc))
                    parts.append(f"[tool_result len={tlen}]")
        summary = " ".join(parts)
    elif isinstance(content, str):
        summary = content[:150].replace("\n"," ")
    print(i, t, ts, role, summary[:200])
