import json
path = "issue10.jsonl"
with open(path) as f:
    lines = f.readlines()

def full_text(idx):
    obj = json.loads(lines[idx])
    content = obj.get("message", {}).get("content") if isinstance(obj.get("message"), dict) else None
    out=[]
    if isinstance(content, list):
        for c in content:
            if isinstance(c, dict):
                if c.get("type")=="text":
                    out.append(c.get("text",""))
                elif c.get("type")=="tool_use":
                    out.append(f"TOOL_USE {c.get('name')} input={json.dumps(c.get('input'))[:500]}")
                elif c.get("type")=="tool_result":
                    tc=c.get("content")
                    if isinstance(tc, list):
                        txt = " ".join(x.get("text","") for x in tc if isinstance(x,dict))
                    else:
                        txt = str(tc)
                    out.append(f"TOOL_RESULT: {txt[:800]}")
    elif isinstance(content,str):
        out.append(content)
    return "\n".join(out)

for i in [62,63,64,248,249,250,251,252,253,254,255,256]:
    print("====", i, "====")
    print(full_text(i)[:1000])
    print()
